// macOS golden-image ops contract tests.
//
// Covers the two artifacts build-golden-image.sh and Task 1.3 depend on:
// the pinned CLI manifest (ops/macos-vm/cli-manifest.txt, generated by
// generate-cli-manifest.sh) and the guest credential probe
// (ops/macos-vm/probe-guest-credentials.sh).
//
// Four things here cannot be checked by reading the scripts:
//
//   1. The manifest has to satisfy the build script's OWN validator, not a
//      restatement of it. So the validator is extracted from
//      build-golden-image.sh and run against the committed manifest — a
//      loosened rule there can never drift away from what is tested here.
//
//   2. The probe's guest half runs under whatever /bin/bash the guest has, and
//      macOS still ships bash 3.2.57. A construct that works in the 5.x on the
//      developer's PATH can fail there, so the generated guest script is
//      syntax-checked and its classifier is executed under /bin/bash.
//
//   3. The classifier must read output, not exit status. Measured 2026-08-14
//      against the pinned CLIs: `cursor-agent status` and `opencode auth list`
//      both exit 0 while logged out. Scoring those by exit code reports a
//      logged-out CLI as ready, which is the wrong "yes" the whole credential
//      table exists to prevent — so those two fixtures are asserted directly.
//
//   4. build-golden-image.sh's `guest_exec_script <<EOF` blocks are a second
//      program. The host expands them, `prlctl exec` feeds them to the guest's
//      bash, and `bash -n` on the outer file never looks inside — so a break
//      there surfaces hours into a rebuild, against a VM, as a guest error. The
//      blocks are rendered and syntax-checked here, and the XcodeGen probe
//      (added after the image shipped a preset-less install twice) is executed
//      against a broken stub and a healthy one.
//
// Nothing here talks to Parallels or boots a VM: the probe is rendered, not
// dispatched.

import { ok, strictEqual } from "node:assert";
import { spawnSync } from "node:child_process";
import {
	accessSync,
	chmodSync,
	constants,
	existsSync,
	mkdtempSync,
	readdirSync,
	readFileSync,
	writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { describe, it } from "node:test";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const PKG_ROOT = resolve(__dirname, "..");
const VM_OPS = resolve(PKG_ROOT, "ops/macos-vm");

const BUILD = resolve(VM_OPS, "build-golden-image.sh");
const GENERATOR = resolve(VM_OPS, "generate-cli-manifest.sh");
const PROBE = resolve(VM_OPS, "probe-guest-credentials.sh");
const MANIFEST = resolve(VM_OPS, "cli-manifest.txt");

const IS_DARWIN = process.platform === "darwin";
const notDarwin = { skip: IS_DARWIN ? false : "macOS-only ops lane" };

// The build script requires exactly these providers, and install_guest_tools
// asserts all are on PATH afterwards.
const REQUIRED_PROVIDERS = [
	"claude",
	"codex",
	"agy",
	"cursor-agent",
	"copilot",
	"opencode",
	"vibe",
];

// The pinned install ref for each provider — the manifest's own record of
// what the golden image installs; a ref drifting here with no test noticing
// would build an image carrying a different CLI than intended.
const EXPECTED_REFS = {
	claude: "https://claude.ai/install.sh",
	codex: "https://chatgpt.com/codex/install.sh",
	agy: "https://antigravity.google/cli/install.sh",
	"cursor-agent": "https://cursor.com/install",
	copilot: "@github/copilot",
	opencode: "opencode-ai",
	vibe: "mistral-vibe",
};

const readManifestRows = () =>
	readFileSync(MANIFEST, "utf8")
		.split("\n")
		.map((line) => line.trim())
		.filter((line) => line.length > 0 && !line.startsWith("#"))
		.map((line) => {
			const [provider, kind, ref, detail, hash, ...rest] = line.split("|");
			return { provider, kind, ref, detail, hash, rest, line };
		});

// Pulls a top-level `name() { ... }` block out of a shell script by matching
// the closing brace in column 1. Every function in these scripts is written
// that way, which is what makes the extraction safe.
const extractShellFunction = (body, name) => {
	const start = body.indexOf(`${name}() {`);
	ok(start !== -1, `no ${name}() in script`);
	const end = body.indexOf("\n}\n", start);
	ok(end !== -1, `unterminated ${name}()`);
	return body.slice(start, end + 3);
};

const scratch = () => mkdtempSync(join(tmpdir(), "switchyard-vm-ops-"));

// Renders every `guest_exec_script <<EOF` block in the build script the way the
// host renders it: the script's own top-level assignments, then `cat <<EOF`.
// Returns one entry per block with the source line it started on, so a failure
// names the block instead of the file.
const renderBuildGuestScripts = (dir) => {
	const lines = readFileSync(BUILD, "utf8").split("\n");
	const preamble = [];
	for (const line of lines) {
		if (/^[a-z_]+\(\) \{/.test(line)) break;
		if (/^(readonly )?[A-Z][A-Z0-9_]*=/.test(line)) preamble.push(line);
	}
	ok(preamble.length > 0, "build script lost its top-level assignments");

	const rendered = [];
	for (let i = 0; i < lines.length; i += 1) {
		if (!/guest_exec_script <<EOF$/.test(lines[i])) continue;
		const end = lines.indexOf("EOF", i + 1);
		ok(end !== -1, `unterminated guest heredoc opened at line ${i + 1}`);
		const harness = join(dir, `render-guest-${rendered.length}.sh`);
		writeFileSync(
			harness,
			[...preamble, "cat <<EOF", ...lines.slice(i + 1, end), "EOF", ""].join(
				"\n",
			),
		);
		const run = spawnSync("/bin/bash", [harness], { encoding: "utf8" });
		strictEqual(
			run.status,
			0,
			`rendering the guest block at line ${i + 1} failed: ${run.stderr}`,
		);
		rendered.push({ line: i + 1, body: run.stdout });
		i = end;
	}
	ok(
		rendered.length >= 3,
		`expected several guest blocks, got ${rendered.length}`,
	);
	return rendered;
};

// Pulls the XcodeGen probe out of a rendered guest block so it can be run
// standalone. It takes the xcodegen path as $1, which is what makes it testable
// against a stub.
const extractProbeScript = (rendered) => {
	const block = rendered.find((entry) =>
		entry.body.includes("<<'PROBE_SCRIPT'"),
	);
	ok(block, "no guest block carries the XcodeGen probe heredoc");
	const start = block.body.indexOf("<<'PROBE_SCRIPT'");
	const bodyStart = block.body.indexOf("\n", start) + 1;
	const end = block.body.indexOf("\nPROBE_SCRIPT\n", bodyStart);
	ok(end !== -1, "unterminated XcodeGen probe heredoc");
	return { block, script: block.body.slice(bodyStart, end + 1) };
};

// Renders the guest-side script the probe would feed to `prlctl exec`, without
// needing Parallels: the one prlctl call is swapped for cat and the running-VM
// precondition is dropped.
const renderGuestScript = (dir) => {
	const rendered = readFileSync(PROBE, "utf8")
		.replace('  prlctl exec "$VM_NAME" /bin/bash -s <<EOF', "  cat <<EOF")
		.replace(/^ {2}require_host_tools$/m, "  true");
	ok(rendered.includes("cat <<EOF"), "probe's prlctl exec call moved");
	// Prose mentions prlctl exec repeatedly; only a command position matters.
	ok(
		!/^\s*prlctl exec\b/m.test(rendered),
		"probe has a second prlctl exec call",
	);
	const harness = join(dir, "render.sh");
	writeFileSync(harness, rendered);
	const run = spawnSync(
		"/bin/bash",
		[harness, "--vm", "probe-vm", "--phase", "baseline"],
		{
			encoding: "utf8",
		},
	);
	strictEqual(run.status, 0, `render failed: ${run.stderr}`);
	return run.stdout;
};

describe("macOS golden-image ops artifacts", () => {
	it("ships the generator, the probe, and a generated manifest", () => {
		for (const script of [BUILD, GENERATOR, PROBE]) {
			ok(existsSync(script), `missing: ${script}`);
			accessSync(script, constants.X_OK);
		}
		ok(existsSync(MANIFEST), `missing: ${MANIFEST}`);
	});

	it("every ops script passes `bash -n`", () => {
		for (const script of [BUILD, GENERATOR, PROBE]) {
			const r = spawnSync("bash", ["-n", script], { encoding: "utf8" });
			strictEqual(r.status, 0, `bash -n failed for ${script}: ${r.stderr}`);
		}
	});

	// Regression, measured in switchyard-check-2 on 2026-08-14. The C-3 block
	// rules carry no direction, so they also drop packets addressed TO
	// 10.0.0.0/8 -- which includes the guest's own shared-network address, which
	// includes the DHCP OFFER. A clone with a fresh MAC therefore never
	// completed a lease, fell back to 169.254, and had no network at all: every
	// provider auth check that needs the network read as unauthenticated. The
	// build VM cannot catch this, because it already holds a lease taken before
	// pf was loaded and renewals are stateful unicast the port-67 rule passes.
	// pf takes the first quick match, so presence is not enough -- order is the
	// property.
	it("passes DHCP in both directions above the C-3 blocks", () => {
		const body = readFileSync(BUILD, "utf8");
		const start = body.indexOf('anchor "switchyard-transfer/*"');
		ok(start !== -1, "C-3 anchor rules moved");
		const end = body.indexOf("\nPFEOF", start);
		ok(end !== -1, "unterminated C-3 anchor heredoc");
		const rules = body
			.slice(start, end)
			.split("\n")
			.filter((line) => !line.trimStart().startsWith("#"));

		const dhcpOut = rules.findIndex((line) =>
			/^pass\s+out quick on en0 proto udp from any port 68 to any port 67$/.test(
				line.replace(/\s+/g, " ").trim(),
			),
		);
		const dhcpIn = rules.findIndex((line) =>
			/^pass\s+in quick on en0 proto udp from any port 67 to any port 68$/.test(
				line.replace(/\s+/g, " ").trim(),
			),
		);
		const firstBlock = rules.findIndex((line) =>
			line.startsWith("block drop quick on en0"),
		);

		ok(dhcpOut !== -1, "no outbound DHCP pass in the C-3 anchor");
		ok(dhcpIn !== -1, "no inbound DHCP pass in the C-3 anchor");
		ok(firstBlock !== -1, "C-3 anchor lost its RFC1918 blocks");
		ok(
			dhcpOut < firstBlock && dhcpIn < firstBlock,
			"a DHCP pass below the blocks never matches: a fresh-MAC clone gets no lease",
		);
	});

	// The CLIs install into the provider's ~/.local/bin, which no default macOS
	// login PATH contains. Measured 2026-08-14: the image shipped with all six
	// present on disk and none resolvable by name from the Aqua session the
	// adapters actually use, so every provider exec would have failed with
	// "command not found".
	it("puts the provider's ~/.local/bin on the login PATH", () => {
		const body = readFileSync(BUILD, "utf8");
		ok(
			/\/etc\/paths\.d\/switchyard/.test(body),
			"the build no longer registers a path_helper entry for the provider CLIs",
		);
		ok(
			/printf '%s\\\\n' "\/Users\/\\\$provider_user\/\.local\/bin" > \/etc\/paths\.d\/switchyard/.test(
				body,
			),
			"the path_helper entry does not name the provider's ~/.local/bin",
		);
	});

	// The installer heredoc exports ~/.local/bin itself, so its own `command -v`
	// sweep passes whether or not a real login can resolve the CLIs. The
	// assertion that matters has to run outside that heredoc, through the same
	// identity the execution backend uses.
	it("resolves every pinned CLI through a fresh provider login", () => {
		const body = readFileSync(BUILD, "utf8");
		const installStart = body.indexOf("INSTALL_SCRIPT");
		const installEnd = body.indexOf("\nINSTALL_SCRIPT", installStart);
		ok(installEnd !== -1, "installer heredoc moved");

		const loginCheck =
			/\/bin\/launchctl asuser "\\\$uid" \/usr\/bin\/sudo -u "\\\$provider_user" \/bin\/bash -lc/;
		const match = body.search(loginCheck);
		ok(match !== -1, "no login-PATH resolution check in the build");
		ok(
			match > installEnd,
			"the login-PATH check sits inside the installer heredoc, which exports the directory and can never fail",
		);
		ok(
			/pinned CLI is not on the provider login PATH/.test(body),
			"the login-PATH check does not fail closed with a distinct message",
		);
	});

	// A lease and a default route arrive before resolution does, and the CLI
	// installers all fetch over the network moments after a restart. Measured
	// 2026-08-14: a build died on `curl: (6) Could not resolve host`.
	it("waits for guest DNS before installing the CLIs, over stdin", () => {
		const body = readFileSync(BUILD, "utf8");
		ok(
			/wait_for_guest_dns\(\)/.test(body),
			"the build no longer gates CLI installation on DNS readiness",
		);
		const installIndex = body.indexOf("install_guest_tools() {");
		ok(installIndex !== -1, "install_guest_tools moved");
		const installBody = body.slice(installIndex, installIndex + 200);
		ok(
			/wait_for_guest_dns/.test(installBody),
			"install_guest_tools does not wait for DNS before fetching installers",
		);

		// The probe is piped, and prlctl reparses an argv-supplied script, so
		// routing it through guest_exec would drop the pipe and the gate would
		// fail for its whole timeout against a guest that resolves fine.
		const gateStart = body.indexOf("wait_for_guest_dns() {");
		const gateBody = body.slice(gateStart, body.indexOf("\n}", gateStart));
		ok(
			/\| guest_exec_script/.test(gateBody),
			"the DNS probe does not use the stdin channel",
		);
		ok(
			!/guest_exec "/.test(gateBody),
			"the DNS probe uses guest_exec, whose argv reparse drops the pipe",
		);
	});

	// `bash -n` on the file above only parses the host half. The guest half is
	// text until the host expands it, and it runs under macOS's bash 3.2.57.
	it("renders guest scripts that parse under the guest's own bash", () => {
		const dir = scratch();
		for (const { line, body } of renderBuildGuestScripts(dir)) {
			const guest = join(dir, `guest-${line}.sh`);
			writeFileSync(guest, body);
			const r = spawnSync("/bin/bash", ["-n", guest], { encoding: "utf8" });
			strictEqual(
				r.status,
				0,
				`the guest block at line ${line} does not parse: ${r.stderr}`,
			);
		}
	});

	// Regression, measured 2026-08-14. `switchyard-golden-6` shipped an XcodeGen
	// whose Cellar held `bin` and nothing else -- no share/xcodegen/SettingPresets
	// -- so every generated project came out with an empty PRODUCT_NAME and
	// SWIFT_VERSION and `xcodebuild` died on "Multiple commands produce .../.app".
	// `xcodegen --version` reports the pinned version perfectly well in that
	// state, so the version guard could never see it. The same defect is visible
	// in the Task 1.3 evidence from a clone of golden-2, which means it shipped in
	// every build of this script.
	it("checks XcodeGen by generating a project, not by its version string", () => {
		const rendered = renderBuildGuestScripts(scratch());
		const { block, script } = extractProbeScript(rendered);

		ok(
			block.body.includes("share/xcodegen/SettingPresets"),
			"the build no longer asserts the XcodeGen preset tree is on disk",
		);
		// brew decides "installed" from the prefix, and the broken Cellar carries
		// no receipt, so `brew reinstall` alone can no-op against this exact state.
		// `uninstall --force` is brew bookkeeping too and can decline a formula it
		// does not consider installed, so the removal the install depends on is the
		// rm -- which needs no bookkeeping to be correct.
		ok(
			/uninstall --force xcodegen/.test(block.body),
			"the XcodeGen repair does not remove the broken install before reinstalling",
		);
		ok(
			/rm -rf "\$brew_path\/Cellar\/xcodegen"/.test(block.body),
			"the XcodeGen repair leaves the broken Cellar directory to brew's bookkeeping, which does not model it",
		);
		// The guest script is root. A root-owned mktemp -d at mode 700 would make
		// the generate fail on permissions and report a cause that is not the
		// cause, so the probe's directory has to be created in the same hop that
		// runs xcodegen.
		ok(
			script.includes('mktemp -d "$HOME/'),
			"the XcodeGen probe does not create its working directory as the build user",
		);
		ok(
			/XcodeGen did not generate a project carrying a product name: \$xcodegen_probe_out/.test(
				block.body,
			),
			"the XcodeGen failure does not carry the probe's own output, so it cannot say why it stopped",
		);
	});

	it("restores Homebrew ownership before using the administrator install session", () => {
		const { block } = extractProbeScript(renderBuildGuestScripts(scratch()));
		const ownershipRepair = block.body.indexOf(
			"restoring Homebrew ownership to the existing administrator build session",
		);
		const nodeInstall = block.body.indexOf(
			"installing Node through the existing administrator build session",
		);
		ok(
			ownershipRepair !== -1,
			"the build does not repair a root-owned Homebrew prefix",
		);
		ok(
			ownershipRepair < nodeInstall,
			"Homebrew ownership is repaired only after an administrator-scoped brew install",
		);
		ok(
			/\/usr\/sbin\/chown -R "\$console_user:admin" "\$brew_path"/.test(
				block.body,
			),
			"the Homebrew repair does not restore the console administrator as owner",
		);
	});

	// Executed, not read: the probe is the thing that has to fail on a
	// preset-less install, and asserting its text cannot show that it does.
	it("fails a preset-less XcodeGen and passes a healthy one", () => {
		const { script } = extractProbeScript(renderBuildGuestScripts(scratch()));
		const dir = scratch();
		const probe = join(dir, "probe.sh");
		writeFileSync(probe, script);

		const stub = (name, body) => {
			const path = join(dir, name);
			writeFileSync(path, `#!/bin/bash\n${body}\n`);
			chmodSync(path, 0o755);
			return path;
		};
		// What the broken image does: exits 0, warns, writes a project whose
		// product name is empty.
		const presetless = stub(
			"xcodegen-preset-less",
			[
				`printf 'No "base" settings found\\n'`,
				"mkdir -p SwitchyardPresetProbe.xcodeproj",
				"printf 'PRODUCT_NAME = \"\";\\n' > SwitchyardPresetProbe.xcodeproj/project.pbxproj",
			].join("\n"),
		);
		const healthy = stub(
			"xcodegen-healthy",
			[
				"mkdir -p SwitchyardPresetProbe.xcodeproj",
				"printf 'path = SwitchyardPresetProbe.app;\\n' > SwitchyardPresetProbe.xcodeproj/project.pbxproj",
			].join("\n"),
		);

		const run = (bin) =>
			spawnSync("/bin/bash", [probe, bin], {
				encoding: "utf8",
				env: { ...process.env, HOME: dir },
			});

		const broken = run(presetless);
		ok(
			broken.stdout.includes('No "base" settings found'),
			"the probe swallowed the preset warning the build greps for",
		);
		ok(
			!broken.stdout.includes("SWITCHYARD_XCODEGEN_PRODUCT_NAME_OK"),
			"the probe passed a preset-less XcodeGen",
		);

		const good = run(healthy);
		strictEqual(
			good.status,
			0,
			`probe failed a healthy install: ${good.stderr}`,
		);
		ok(
			good.stdout.includes("SWITCHYARD_XCODEGEN_PRODUCT_NAME_OK"),
			"the probe does not signal success on a healthy install",
		);
		ok(
			!readdirSync(dir).some((entry) =>
				entry.startsWith(".switchyard-xcodegen-probe."),
			),
			"the probe left its working directory in the image",
		);
	});

	// Regression, from the credential probe's own history: that script is fed to
	// `bash -s`, `agy` read stdin when it decided to prompt, and it swallowed the
	// script tail -- three provider checks silently never ran and nothing failed.
	// The XcodeGen probe arrives the same way, so it gets the same `</dev/null`.
	// Feeding the probe on stdin here is what makes the test able to see it: as a
	// file argument the shell can seek back and the defect cannot reproduce.
	it("does not let xcodegen eat the rest of the probe", () => {
		const { script } = extractProbeScript(renderBuildGuestScripts(scratch()));
		const dir = scratch();
		const greedy = join(dir, "xcodegen-greedy");
		writeFileSync(
			greedy,
			[
				"#!/bin/bash",
				// Exactly what a CLI that prompts does to a piped script.
				"cat >/dev/null",
				"mkdir -p SwitchyardPresetProbe.xcodeproj",
				"printf 'path = SwitchyardPresetProbe.app;\\n' > SwitchyardPresetProbe.xcodeproj/project.pbxproj",
				"",
			].join("\n"),
		);
		chmodSync(greedy, 0o755);

		const run = spawnSync("/bin/bash", ["-s", "--", greedy], {
			encoding: "utf8",
			input: script,
			env: { ...process.env, HOME: dir },
		});
		ok(
			run.stdout.includes("SWITCHYARD_XCODEGEN_PRODUCT_NAME_OK"),
			"a stdin-reading xcodegen ate the probe's remaining lines, so the check silently never ran",
		);
	});
});

describe("the pinned CLI manifest", () => {
	it("passes build-golden-image.sh's own validator", notDarwin, () => {
		const body = readFileSync(BUILD, "utf8");
		const dir = scratch();
		const harness = join(dir, "validate.sh");
		// log() and fail() are what the validator reports through; take them
		// from the same file rather than restating them.
		writeFileSync(
			harness,
			[
				"#!/bin/bash",
				"set -Eeuo pipefail",
				'readonly SCRIPT_NAME="validator-harness"',
				extractShellFunction(body, "log"),
				extractShellFunction(body, "fail"),
				extractShellFunction(body, "validate_cli_manifest"),
				`CLI_MANIFEST=${JSON.stringify(MANIFEST)}`,
				"validate_cli_manifest",
				'printf "MANIFEST OK\\n"',
			].join("\n"),
		);
		const r = spawnSync("bash", [harness], { encoding: "utf8" });
		strictEqual(r.status, 0, `validator rejected the manifest: ${r.stderr}`);
		ok(r.stdout.includes("MANIFEST OK"));
	});

	it("covers exactly the providers the build asserts on PATH", () => {
		const rows = readManifestRows();
		strictEqual(rows.length, REQUIRED_PROVIDERS.length);
		const providers = rows.map((row) => row.provider).sort();
		strictEqual(providers.join(","), [...REQUIRED_PROVIDERS].sort().join(","));
	});

	it("pins each ref to the expected install source", () => {
		for (const row of readManifestRows()) {
			strictEqual(
				row.ref,
				EXPECTED_REFS[row.provider],
				`manifest ref drifted for ${row.provider}`,
			);
		}
	});

	it("carries a full sha256 on every row and a version on every npm row", () => {
		for (const row of readManifestRows()) {
			strictEqual(row.rest.length, 0, `trailing field: ${row.line}`);
			ok(/^[0-9a-f]{64}$/.test(row.hash), `not a sha256: ${row.line}`);
			if (row.kind === "npm" || row.kind === "brew") {
				// The npm rows are the only version-pinned ones; the script refs
				// are unversioned endpoints held in place by the hash alone.
				ok(
					/^[0-9][0-9A-Za-z.+_-]*$/.test(row.detail),
					`bad version: ${row.line}`,
				);
			} else {
				strictEqual(row.kind, "script");
				ok(
					row.detail === "bash" || row.detail === "sh",
					`bad shell: ${row.line}`,
				);
				ok(
					row.ref.startsWith("https://"),
					`installer must be HTTPS: ${row.line}`,
				);
			}
		}
	});

	it("is generated, and says so, so no one hand-edits a hash", () => {
		const header = readFileSync(MANIFEST, "utf8");
		ok(/GENERATED BY generate-cli-manifest\.sh/.test(header));
		ok(/Do not hand-edit a hash/.test(header));
	});

	it("has a generator that refuses an npm row the registry does not confirm", () => {
		const body = readFileSync(GENERATOR, "utf8");
		// The npm rows are the only ones with an independent witness; losing
		// that check would silently downgrade them to "whatever this host had".
		ok(body.includes("dist.tarball"), "generator no longer reads dist.tarball");
		ok(
			/\[\[ "\$packed_hash" == "\$registry_hash" \]\] \|\|/.test(body),
			"generator no longer compares the packed and registry tarballs",
		);
	});
});

describe("the guest credential probe", () => {
	it(
		"renders a guest script that is syntax-clean under bash",
		notDarwin,
		() => {
			const dir = scratch();
			const guest = join(dir, "guest.sh");
			writeFileSync(guest, renderGuestScript(dir));
			const r = spawnSync("/bin/bash", ["-n", guest], { encoding: "utf8" });
			strictEqual(r.status, 0, `guest script is not valid bash: ${r.stderr}`);
		},
	);

	it(
		"routes every check through the provider's Aqua session",
		notDarwin,
		() => {
			const guest = renderGuestScript(scratch());
			// prlctl exec lands as root in the System domain; the CLIs live in the
			// auto-login account's Aqua session and the two see different Keychains.
			ok(
				/\/bin\/launchctl asuser "\$uid" \/usr\/bin\/sudo -iu "\$provider_user"/.test(
					guest,
				),
				"probe no longer enters the Aqua session the way install_guest_tools does",
			);
			ok(
				/launchctl managername/.test(guest),
				"probe no longer reports which domain it measured",
			);
		},
	);

	it("never asks the Keychain for secret data", () => {
		const body = readFileSync(PROBE, "utf8");
		const dumps = body.match(/security dump-keychain[^\n|]*/g) ?? [];
		ok(dumps.length > 0, "probe no longer enumerates the Keychain");
		for (const call of dumps) {
			ok(!/\s-d\b/.test(call), `dump-keychain must never use -d: ${call}`);
		}
		ok(
			!/security\s+find-generic-password[^\n]*-w/.test(body),
			"probe must not print a password",
		);
	});

	it(
		"scores the measured CLI outputs by output, not exit status",
		notDarwin,
		() => {
			const guest = renderGuestScript(scratch());
			const dir = scratch();
			const harness = join(dir, "classify.sh");
			writeFileSync(
				harness,
				[
					"set -uo pipefail",
					extractShellFunction(guest, "bounded"),
					extractShellFunction(guest, "classify"),
					// awk, not `head -1`: head would close the pipe early and
					// pipefail would surface classify's SIGPIPE as a harness failure.
					"verdict() {",
					'  classify "$@" | awk -F"\\t" \'NR==1 {print $2}\'',
					"}",
				].join("\n"),
			);

			// provider, unauth regex, auth rule, fixture stdout, fixture exit, want.
			// Every fixture is a real output captured from the pinned CLIs on
			// 2026-08-14 in a credential-free container.
			const cases = [
				[
					"claude",
					'"loggedIn": false',
					'"loggedIn": true',
					'{\n  "loggedIn": false\n}',
					1,
					"unauthenticated",
				],
				[
					"claude",
					'"loggedIn": false',
					'"loggedIn": true',
					'{\n  "loggedIn": true\n}',
					0,
					"authenticated",
				],
				[
					"codex",
					"Not logged in",
					"Logged in",
					"Not logged in",
					1,
					"unauthenticated",
				],
				[
					"agy",
					"Please sign in|authentication required",
					"gemini-",
					"Error: Please sign in to view available models.",
					1,
					"unauthenticated",
				],
				// agy words its refusal differently in the VM than in the container.
				// Measured in switchyard-check-2 on 2026-08-14; the container fixture
				// above is the same day. Both must score unauthenticated.
				[
					"agy",
					"Please sign in|authentication required",
					"gemini-",
					"Error: authentication required. Run 'agy' to log in, then retry.",
					1,
					"unauthenticated",
				],
				[
					"agy",
					"Please sign in|authentication required",
					"gemini-",
					"gemini-3.7-flash-medium",
					0,
					"authenticated",
				],
				// The two that exit 0 while logged out.
				[
					"cursor-agent",
					"Not logged in",
					"Logged in|Email|Account",
					"Not logged in",
					0,
					"unauthenticated",
				],
				[
					"opencode",
					"0 credentials",
					"[1-9][0-9]* credentials",
					"0 credentials",
					0,
					"unauthenticated",
				],
				[
					"opencode",
					"0 credentials",
					"[1-9][0-9]* credentials",
					"3 credentials",
					0,
					"authenticated",
				],
				[
					"copilot",
					"No authentication information found",
					"exit0",
					"Error: No authentication information found.",
					1,
					"unauthenticated",
				],
				[
					"copilot",
					"No authentication information found",
					"exit0",
					"ok",
					0,
					"authenticated",
				],
				// A transport failure is neither, and must not be scored as a pass.
				[
					"copilot",
					"No authentication information found",
					"exit0",
					"fetch failed",
					1,
					"indeterminate",
				],
			];

			for (const [provider, unauth, rule, output, status, want] of cases) {
				const fixture = join(dir, "fixture.sh");
				writeFileSync(
					fixture,
					`printf '%s\\n' ${JSON.stringify(output)}\nexit ${status}\n`,
				);
				const r = spawnSync(
					"/bin/bash",
					[
						"-c",
						`. ${JSON.stringify(harness)}; verdict "$@"`,
						"harness",
						provider,
						unauth,
						rule,
						"/bin/sh",
						fixture,
					],
					{ encoding: "utf8" },
				);
				strictEqual(r.status, 0, `classify harness failed: ${r.stderr}`);
				strictEqual(
					r.stdout.trim(),
					want,
					`${provider} with output ${JSON.stringify(output)} exit ${status}`,
				);
			}
		},
	);

	it("bounds a hung provider check without coreutils", notDarwin, () => {
		const guest = renderGuestScript(scratch());
		const dir = scratch();
		const harness = join(dir, "bounded.sh");
		writeFileSync(
			harness,
			`set -uo pipefail\n${extractShellFunction(guest, "bounded")}\n`,
		);
		const started = Date.now();
		const r = spawnSync(
			"/bin/bash",
			["-c", `. ${JSON.stringify(harness)}; bounded 1 /bin/sleep 30`],
			{ encoding: "utf8" },
		);
		const elapsed = Date.now() - started;
		ok(r.status !== 0, "a hung check must not report success");
		ok(elapsed < 10_000, `alarm did not fire: ${elapsed}ms`);
	});

	// Regression, found on the first real guest run (2026-08-14): the probe is
	// itself delivered to `bash -s` on stdin, so a provider that reads stdin --
	// agy does, when it decides to prompt for a login -- swallows the remainder
	// of the script. The baseline run ended silently after agy and never ran
	// cursor-agent, copilot, or opencode. Nothing failed; three rows just
	// disappeared, which is the worst shape a credential probe can fail in.
	it(
		"does not let a provider check eat the rest of the script",
		notDarwin,
		() => {
			const guest = renderGuestScript(scratch());
			const dir = scratch();
			const harness = join(dir, "stdin.sh");
			writeFileSync(
				harness,
				[
					"set -uo pipefail",
					extractShellFunction(guest, "bounded"),
					extractShellFunction(guest, "classify"),
					// /bin/cat is the minimal stand-in for a stdin-reading provider.
					"classify greedy no-such-string exit0 /bin/cat >/dev/null 2>&1",
					'printf "SURVIVED\\n"',
				].join("\n"),
			);
			const r = spawnSync("/bin/bash", ["-s"], {
				encoding: "utf8",
				input: readFileSync(harness, "utf8"),
			});
			strictEqual(
				r.stdout.trim(),
				"SURVIVED",
				"a stdin-reading provider consumed the script tail",
			);
		},
	);
});

// Clipboard isolation (INV-1). Three defects fixed together, because the image
// protects itself by a launchd override now rather than by the plist's absence,
// which inverts what the structural assertion must check:
//
//   1. A Guest Tools update restores a renamed plist (observed 2026-08-21) but
//      cannot re-enable a label disabled in /var/db/com.apple.xpc.launchd.
//   2. The assertion signalled through an exit code, so a probe that could not
//      run and a probe that found isolation were indistinguishable — the
//      failure mode that reports a broken gate as green.
//   3. It tested only host-to-guest, while prlcopypaste syncs both ways.
//
// Everything below executes the extracted shell, against stubs. Reading the
// script cannot show that a negative case actually fails the build.
describe("clipboard isolation posture", () => {
	const buildBody = () => readFileSync(BUILD, "utf8");

	const stubIn = (dir, name, body) => {
		const path = join(dir, name);
		writeFileSync(path, `#!/bin/bash\n${body}\n`);
		chmodSync(path, 0o755);
		return path;
	};

	// The guest posture check uses absolute paths, which no PATH stub can
	// intercept. Pull the two clipboard lines out of the rendered guest block
	// and point /bin/launchctl at a stub, so the committed assertion text is
	// what runs.
	const clipboardPostureHarness = (dir, launchctlStub) => {
		const rendered = renderBuildGuestScripts(dir);
		// Two blocks mention the label: the one that disables it and the one
		// that asserts the posture. Select on the assertion, not the label.
		const block = rendered.find((entry) =>
			entry.body.includes("launchctl print-disabled"),
		);
		ok(block, "no rendered guest block asserts on the clipboard label");
		const lines = block.body.split("\n");
		const first = lines.findIndex((line) =>
			line.includes("launchctl print-disabled"),
		);
		ok(first !== -1, "the guest block no longer checks the override database");
		const last = lines.findIndex(
			(line, i) => i > first && line.includes("clipboard service is loaded"),
		);
		ok(
			last !== -1,
			"the guest block no longer checks that the service resolves",
		);
		const assertion = lines
			.slice(first, last + 1)
			.join("\n")
			.replaceAll("/bin/launchctl", launchctlStub);
		const harness = join(dir, "posture.sh");
		writeFileSync(
			harness,
			[
				"#!/bin/bash",
				'fail_guest() { printf "GUEST-FAIL: %s\\n" "$*"; exit 9; }',
				'uid="501"',
				assertion,
				'printf "POSTURE-OK\\n"',
				"",
			].join("\n"),
		);
		return harness;
	};

	const runPosture = (printDisabled, printResolves) => {
		const dir = scratch();
		const stub = stubIn(
			dir,
			"launchctl",
			[
				'if [[ "$1" == "print-disabled" ]]; then',
				`  printf '%s\\n' ${JSON.stringify(printDisabled)}`,
				"  exit 0",
				"fi",
				'if [[ "$1" == "print" ]]; then',
				`  exit ${printResolves ? 0 : 1}`,
				"fi",
				"exit 0",
			].join("\n"),
		);
		return spawnSync("/bin/bash", [clipboardPostureHarness(dir, stub)], {
			encoding: "utf8",
		});
	};

	const DISABLED = '\t\t"com.parallels.copypaste" => disabled';

	it("passes only when the label is disabled and the service does not resolve", () => {
		const run = runPosture(DISABLED, false);
		strictEqual(run.status, 0, `hardened posture rejected: ${run.stdout}`);
		ok(run.stdout.includes("POSTURE-OK"));
	});

	it("accepts the older `=> true` rendering, which launchd owns, not us", () => {
		const run = runPosture('\t\t"com.parallels.copypaste" => true', false);
		strictEqual(run.status, 0, `posture rejected => true: ${run.stdout}`);
	});

	it("fails the build when the override database does not report the label disabled", () => {
		const run = runPosture('\t\t"com.parallels.copypaste" => enabled', false);
		strictEqual(run.status, 9, `an enabled label was accepted: ${run.stdout}`);
		ok(run.stdout.includes("not disabled in the launchd override database"));
	});

	it("fails the build when the label is absent from the override database entirely", () => {
		const run = runPosture('\t\t"com.apple.something.else" => disabled', false);
		strictEqual(
			run.status,
			9,
			`a missing override was accepted: ${run.stdout}`,
		);
	});

	it("fails the build when the service still resolves under launchctl print", () => {
		const run = runPosture(DISABLED, true);
		strictEqual(
			run.status,
			9,
			`a resolving service was accepted: ${run.stdout}`,
		);
		ok(run.stdout.includes("clipboard service is loaded"));
	});

	it("enforces the posture through `launchctl disable`, not by moving the plist", () => {
		const body = buildBody();
		ok(
			/launchctl disable "gui\/\\\$console_uid\/com\.parallels\.copypaste"/.test(
				body,
			),
			"the build no longer disables the label through the override database",
		);
		ok(
			!body.includes("com.parallels.copypaste.plist.switchyard-disabled"),
			"the build still renames the plist, which a Guest Tools update undoes",
		);
		ok(
			!/test ! -e \/Library\/LaunchAgents\/com\.parallels\.copypaste\.plist/.test(
				body,
			),
			"the build still asserts the plist is absent, which a disabled label is not",
		);
	});

	// The sentinel and the two-direction assertion, executed against stubs.
	const clipboardHarness = (dir, { guestScript, pbpaste = "" }) => {
		const body = buildBody();
		const harness = join(dir, "clipboard.sh");
		writeFileSync(
			harness,
			[
				"#!/bin/bash",
				'PROVIDER_USER="switchyard"',
				'log() { printf "LOG: %s\\n" "$*" >&2; }',
				'fail() { printf "FAIL: %s\\n" "$*"; exit 7; }',
				`pbcopy() { cat > "${join(dir, "host-pasteboard")}"; }`,
				`pbpaste() { printf '%s' ${JSON.stringify(pbpaste)}; }`,
				`guest_exec_script() { cat >/dev/null; ${guestScript} }`,
				extractShellFunction(body, "clipboard_sentinel"),
				extractShellFunction(body, "assert_clipboard_isolation"),
				'if [[ "$1" == "sentinel" ]]; then clipboard_sentinel; printf "\\n"; clipboard_sentinel; printf "\\n"; exit 0; fi',
				"assert_clipboard_isolation",
				'printf "CLIPBOARD-OK\\n"',
				"",
			].join("\n"),
		);
		return harness;
	};

	// A guest stub that answers each direction in turn, since
	// assert_clipboard_isolation calls guest_exec_script twice.
	const twoAnswers = (first, second) =>
		[
			`if [[ ! -f "$0.turn" ]]; then`,
			`  printf 'x' > "$0.turn"`,
			`  printf '%s\\n' ${JSON.stringify(first)}`,
			"else",
			`  printf '%s\\n' ${JSON.stringify(second)}`,
			"fi",
		].join("\n");

	const ISOLATED =
		"clipboard-probe: direction=host-to-guest origin=guest verdict=sentinel-absent bytes=0";
	const COPIED =
		"clipboard-probe: direction=guest-to-host origin=guest verdict=copied bytes=44";

	const runClipboard = (opts) => {
		const dir = scratch();
		return spawnSync("/bin/bash", [clipboardHarness(dir, opts)], {
			encoding: "utf8",
		});
	};

	it("mints a different sentinel on every invocation", () => {
		const dir = scratch();
		const run = spawnSync(
			"/bin/bash",
			[clipboardHarness(dir, { guestScript: "true;" }), "sentinel"],
			{ encoding: "utf8" },
		);
		strictEqual(run.status, 0, run.stderr);
		const [first, second] = run.stdout.trim().split("\n");
		ok(first?.startsWith("switchyard-clipboard-"), `unexpected: ${first}`);
		ok(
			first !== second,
			`two consecutive sentinels collided: ${first} === ${second}`,
		);
	});

	it("passes when both directions report isolation", () => {
		const run = runClipboard({ guestScript: twoAnswers(ISOLATED, COPIED) });
		strictEqual(run.status, 0, `isolated image rejected: ${run.stdout}`);
		ok(run.stdout.includes("CLIPBOARD-OK"));
	});

	it("fails when the host sentinel is visible in the guest", () => {
		const run = runClipboard({
			guestScript: twoAnswers(
				"clipboard-probe: direction=host-to-guest origin=guest verdict=sentinel-visible bytes=44",
				COPIED,
			),
		});
		strictEqual(run.status, 7, `a live leak passed: ${run.stdout}`);
		ok(run.stdout.includes("reached the guest"));
	});

	// The defect this replaces: an exit code made these two identical.
	it("fails, rather than passes, when the host-to-guest probe could not run", () => {
		const run = runClipboard({ guestScript: twoAnswers("", COPIED) });
		strictEqual(run.status, 7, `a probe that never ran passed: ${run.stdout}`);
		ok(run.stdout.includes("host-to-guest clipboard probe did not run"));
	});

	it("fails when the guest's pbpaste is unavailable, instead of reading absence as isolation", () => {
		const run = runClipboard({
			guestScript: twoAnswers(
				"clipboard-probe: direction=host-to-guest verdict=probe-failed reason=pbpaste-status-127",
				COPIED,
			),
		});
		strictEqual(run.status, 7, `an unavailable pbpaste passed: ${run.stdout}`);
		ok(run.stdout.includes("did not run"));
	});

	it("asserts the guest-to-host direction, and fails when the guest sentinel reaches the host", () => {
		// The host pasteboard hands back whatever the guest copied. The stub
		// echoes the guest's own sentinel, which is the breach.
		const dir = scratch();
		const harness = join(dir, "leak.sh");
		const body = buildBody();
		writeFileSync(
			harness,
			[
				"#!/bin/bash",
				'PROVIDER_USER="switchyard"',
				'log() { printf "LOG: %s\\n" "$*" >&2; }',
				'fail() { printf "FAIL: %s\\n" "$*"; exit 7; }',
				"pbcopy() { cat >/dev/null; }",
				// After the guest copies, the host sees the guest's sentinel.
				'pbpaste() { if [[ -f "$0.leaked" ]]; then printf "%s" "$guest_sentinel"; fi; }',
				`guest_exec_script() { cat >/dev/null; ${twoAnswers(ISOLATED, COPIED)}; printf 'x' > "$0.leaked"; }`,
				extractShellFunction(body, "clipboard_sentinel"),
				extractShellFunction(body, "assert_clipboard_isolation"),
				"assert_clipboard_isolation",
				'printf "CLIPBOARD-OK\\n"',
				"",
			].join("\n"),
		);
		const run = spawnSync("/bin/bash", [harness], { encoding: "utf8" });
		strictEqual(run.status, 7, `a guest-to-host leak passed: ${run.stdout}`);
		ok(
			run.stdout.includes("reached the host pasteboard"),
			`wrong failure: ${run.stdout}`,
		);
	});

	it("fails when the guest never confirmed its own copy, so host absence proves nothing", () => {
		const run = runClipboard({
			guestScript: twoAnswers(
				ISOLATED,
				"clipboard-probe: direction=guest-to-host verdict=probe-failed reason=guest-copy-not-readable",
			),
		});
		strictEqual(
			run.status,
			7,
			`an unconfirmed guest copy passed: ${run.stdout}`,
		);
		ok(run.stdout.includes("guest-to-host clipboard probe did not run"));
	});
});
